-- Iceberg：分区演进无需重写数据
ALTER TABLE catalog.db.events ADD PARTITION FIELD days(event_time);
-- 读历史快照
SELECT * FROM catalog.db.events VERSION AS OF 8473928479283;
-- 合并小文件 + 过期快照
CALL catalog.system.rewrite_data_files(table => 'db.events', options => map('target-file-size-bytes','536870912'));
CALL catalog.system.expire_snapshots(table => 'db.events', older_than => TIMESTAMP '2026-06-01 00:00:00', retain_last => 5);

-- Hudi：MOR 表 upsert（CDC 入湖典型用法）
-- 关键参数：hoodie.datasource.write.table.type=MERGE_ON_READ
-- precombine.field=ts, recordkey.field=id, partitionpath.field=dt
MERGE INTO hudi_orders t USING cdc_stream s ON t.id = s.id
WHEN MATCHED AND s._op = 'D' THEN DELETE
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- Delta：MERGE + 时间旅行 + OPTIMIZE
MERGE INTO delta.`/lake/orders` t USING updates s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET * WHEN NOT MATCHED THEN INSERT *;
SELECT * FROM delta.`/lake/orders` VERSION AS OF 42;
OPTIMIZE delta.`/lake/orders` ZORDER BY (user_id);
VACUUM delta.`/lake/orders` RETAIN 168 HOURS;
